-- Mod-authored victory and defeat screen descriptions, ko_KR overlay.
-- Baseline in CivVAccess_VictoryDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_MISSING"] = "이 화면에 대한 설명이 없습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_CULTURAL"] =
    "어두운 나무 그늘이 드리운 풀이 우거진 언덕 꼭대기에서, 두 인물이 실루엣으로 앉아 황금빛 도시를 내려다보고 있습니다. 그들 아래로는 군중이 받침대 위 고전 양식 조각상들이 늘어선 아치형 돌다리를 건너고 있으며, 그 뒤로 돔 지붕의 홀이 솟아 있습니다. 공원처럼 펼쳐진 녹지 너머로 도시의 윤곽선은 가느다란 미래풍의 탑들로 솟아오르다가 호박색 안개 속으로 녹아듭니다. 잔디밭 곳곳에 사람들이 흩어져 있습니다. 아이들은 실에 매달려 높이 떠오른 연 아래에서 뛰놀고, 한 인물은 노란 양산을 쓰고 거닐며, 안개 너머 먼 수면 위에는 흰 돛이 보입니다. 장면 전체가 따뜻한 황금빛에 잠겨 있어 반쯤은 늦은 오후 같고 반쯤은 꿈결 같으며, 하늘에는 새들이 흩어져 날고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_DIPLOMATIC"] =
    "국제 연합 본부의 높고 흰 석판 같은 건물 앞 푸른 잔디밭에서 열리는 의식입니다. 전경에는 군중이 보는 이를 등진 채 서 있으며, 여러 나라의 정장과 로브와 머릿수건 차림이고, 오른쪽에서는 텔레비전 카메라맨이 삼각대를 세우고 촬영하고 있습니다. 잔디밭을 빙 둘러 깃대들이 수십 개의 국기를 내걸고 있으며, 그중 미국과 멕시코의 국기를 알아볼 수 있습니다. 중앙에는 가지를 넓게 드리운 나무들 아래 네모난 받침대 위에 거대한 돌 지구의가 놓여 있으며, 그 표면에는 대륙들이 도드라지게 새겨져 있습니다. 그 앞에는 여러 나라의 민속 의상을 입은 아이들이 줄지어 기다리고 있으며, 파란 옷을 입은 여인이 몸을 굽혀 노란 드레스를 입은 작은 소녀에게 무언가를 건네고 소녀는 그것을 받으려 손을 위로 뻗고 있습니다. 화면 아래쪽 가장자리에는 붉은색과 흰색 꽃밭이 잔잔한 연못을 두르고 있으며, 부드러운 잿빛 햇살이 모든 것을 고르게 비춥니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_DOMINATION"] =
    "온통 금색과 올리브색과 붉은색의 포스터 같은 색조로 그려진 승전 행진입니다. 오른쪽 전경에는 어깨에 금색 장식 끈을 단 흰 예복 차림의 젊은 장교가 하늘을 가로질러 휘날리는 거대한 붉은 깃발의 깃대를 쥐고 있으며, 그의 챙 달린 모자에는 붉은 띠가 둘리고 금색 휘장이 달려 있습니다. 그의 뒤로는 같은 흰 군복을 입은 병사들이 대오를 이루어 총검을 꽂은 소총을 어깨에 곧추세우고 서 있으며, 행렬 위로 더 많은 붉은 깃발이 솟아 있습니다. 행진 위쪽으로는 성큼 내딛는 말에 탄 지휘관의 청동 기마상이 높은 받침대 위에 서 있고, 그 뒤로 거대한 돔 지붕의 의사당 건물이 있습니다. 가느다란 붉은 현수막들이 빛나는 황록색 하늘을 가로질러 리본처럼 흩날리며, 어두운 사이프러스 나무들과 안개 낀 산들이 먼 배경을 가로막고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_SPACE_RACE"] =
    "깊은 우주에서, 아래쪽에서 거대한 궤도 정거장을 올려다보는 장면입니다. 그 어두운 선체가 화면 위쪽을 가로질러 뻗어 있으며, 아랫면을 따라 따뜻한 빛이 새어 나오는 높은 창들과 초록빛으로 빛나는 격납고들이 줄지어 있습니다. 금속 위로는 증기의 줄기가 흩날립니다. 격자무늬의 평평한 태양 전지판들이 골조 붐을 따라 선체에서 뻗어 나오고, 패널로 덮인 긴 트러스 탑이 선체 먼 끝에서 화면 오른쪽 아래로 드리워져 있습니다. 그 아래로는 한 행성의 밤 쪽 면이 짙은 보라색과 와인색으로 멀어지며, 그 지평선이 장면 아래쪽을 가로질러 호를 그립니다. 태양은 그 지평선 위로 막 떠오르며 흰 금빛 섬광을 내뿜어 곡선을 따라 장밋빛과 크림색 구름의 띠를 밝힙니다. 전경에는 날개 달린 외로운 우주선 한 척이 길고 빛나는 청록색 항적을 남기며 어둠을 가로지르고, 더 작은 선체들이 멀리 별을 배경으로 초록색과 주황색으로 반짝입니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_TIME"] =
    "게임 자체의 표지 그림을 화면 가득 채우도록 확대한 것입니다. 오래된 세피아색 지도 조각들을 이어 붙여 만든 지구의가 화면을 압도하며, 그 위로 Sid Meier's Civilization이라는 제목이 광택 나는 양각 금속 글자로 가로질러 새겨져 있고, 거대한 놋쇠 로마 숫자 5를 꿰뚫고 지나갑니다. 왼쪽 위에는 낡은 핀란드 우표 한 장이 붙어 있는데, 칼레발라 서사시를 기념하여 장식한 말에 탄 기수를 담고 있습니다. 그 주위에는 흐릿한 소인이 잉크로 찍혀 있습니다. 지구의 뒤로는 청록빛으로 물든 종이의 콜라주가 깔려 있고, 놋쇠 자오환 고리가 지구의 아래쪽 가장자리를 둘러 호를 그리며, 빛은 마치 등불 아래 진열된 골동품을 비추듯 왼쪽 위에서 비쳐 듭니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_DEFEAT"] =
    "사막 하늘 아래 멸망한 제국입니다. 거대한 석상의 머리가 모래 위에 뺨을 대고 누워 있으며, 눈은 감겨 있고 얼굴은 평온하며, 그 옆에서는 부서진 돌 손이 손가락을 하늘을 향해 구부린 채 땅에서 솟아 나와 있습니다. 그 주위를 발굴 현장이 둘러싸고 있습니다. 전경의 흙에는 도랑이 파여 있고, 말뚝과 철사로 된 울타리 선이 늘어서 있으며, 연한 옷을 입은 외로운 인물 하나가 나무 계단 발판 위에 서서 자신이 살피는 얼굴 앞에서 한없이 작아 보입니다. 왼쪽 한편에는 짐 나르는 짐승 한 마리가 기다리고 있습니다. 텅 빈 계곡은 흩어진 채 서 있는 파편들을 지나 지평선의 꼭대기가 평평한 메사들까지 뒤로 뻗어 나갑니다. 모든 것이 옅은 파란 하늘 아래 황갈색과 녹슨 빛으로 물들어 있으며, 셸리의 오지만디아스에 나오는 외롭고 평평한 모래밭이 저 멀리까지 펼쳐져 있습니다."
